// for sentence-start usage.
const portalDisplayNameInline = REMOTE_CONTROL_LABEL.toLowerCase();

/**
 * Page ids that only survive as compatibility aliases opening another
 * destination, so the catalog never advertises them. The agent should call that
 * destination's own action instead: plugins.open_management with section mcp,
 * or navigation.open_settings with section environment.
 */
const COMPATIBILITY_ALIAS_NAVIGATION_PAGES: ReadonlySet<NavigationPage> =
  new Set<NavigationPage>([
    'mcp-account-connections',
    'environments',
    'cloud-chat',
  ]);

export type AppAdvisorActionField = AgentActionField;

interface AppAdvisorActionSearchExtras {
  hookTriggers: readonly HookWatcherTriggerCatalogEntry[];
}

export type AppAdvisorActionCatalogEntry = AgentActionCatalogEntry<
  AppAdvisorAction['type'],
  AppAdvisorAction
> &
  Partial<AppAdvisorActionSearchExtras> & {
    /** Accepted compatibility adapter omitted from action discovery. */
    hidden?: boolean;
  };

export interface SearchAppAdvisorActionsInput extends AgentActionSearchInput {
  /** Renderer decisions from a fresh UI snapshot; missing means unknown. */
  availablePages?: readonly string[];
}

export type SearchAppAdvisorActionsResult = AgentActionSearchResult<
  AgentActionSearchResultAction<
    AppAdvisorActionCatalogEntry,
    AppAdvisorActionSearchExtras
  >
>;

