const PROJECT_FIELD: AppAdvisorActionField = {
  name: 'projectId',
  type: 'string',
  required: true,
  description: `${appName} project/workspace id from current UI state.`,
};

const WORKTREE_FIELD: AppAdvisorActionField = {
  name: 'worktreeId',
  type: 'string',
  required: true,
  description: `${appName} worktree id from current UI state.`,
};

const EXECUTION_FIELD: AppAdvisorActionField = {
  name: 'executionId',
  type: 'string',
  required: true,
  description: 'Pipeline execution id.',
};

function field(
  name: string,
  type: string,
  required: boolean,
  description: string,
): AppAdvisorActionField {
  return { name, type, required, description };
}

// The shared project and bot rows, in App Advisor's own order, which its
// search ranking ties depend on.
const PROJECT_BOT_ROWS = [
  ...CHAT_CREATION_ACTION_TYPES,
  ...PROJECT_MESSAGE_CONTROL_ACTION_TYPES,
  ...CHAT_SEND_ACTION_TYPES,
  ...PROJECT_DISCOVERY_ACTION_TYPES,
  ...PROJECT_READ_ACTION_TYPES,
  ...BOT_ACTION_TYPES,
].flatMap((type) =>
  [...PROJECT_ACTION_CATALOG, ...BOT_ACTION_CATALOG].filter(
    (entry) => entry.type === type,
  ),
);

