// Compatibility projection for snapshots predating availablePages. This is
// deliberately conservative metadata, not a main-process gate evaluator.
const PAGES_REQUIRING_AVAILABILITY: ReadonlySet<NavigationPage> =
  new Set<NavigationPage>([
    // Labs page experiments, off by default (CAN-3678).
    'overview',
    'kanban',
    'statistics',
    'audit',
    'workers',
    'header-states',
    'worktree-states',
    'activity-states',
    'message-bubble-states',
    'change-review',
    'notice-states',
  ]);

function projectPageAvailability(
  entry: AppAdvisorActionCatalogEntry,
  availablePages: readonly NavigationPage[],
  input: SearchAppAdvisorActionsInput,
): AppAdvisorActionCatalogEntry | undefined {
  if (entry.type.startsWith('agents.')) {
    if (
      input.featureFlags?.[
        CLIENT_FEATURE_FLAGS.canopySharedCustomAgents.key
      ] !== true
    ) {
      return undefined;
    }
    // Only navigation depends on a page. Local and shared resource operations
    // keep their own authorization, even when Marketplace is unavailable.
    if (
      entry.type === 'agents.open_manager' &&
      (!Array.isArray(input.availablePages) ||
        !availablePages.includes('plugins'))
    ) {
      return undefined;
    }
  }
  if (entry.type !== 'navigation.go_to_page') return entry;
  const examplePage = availablePages.includes('automations')
    ? 'automations'
    : availablePages[0];
  if (!examplePage) return undefined;
  return {
    ...entry,
    fields: entry.fields.map((fieldEntry) =>
      fieldEntry.name === 'page'
        ? {
            ...fieldEntry,
            type: availablePages.map((page) => `'${page}'`).join(' | '),
          }
        : fieldEntry,
    ),
    example:
      examplePage === 'automations'
        ? entry.example
        : { type: 'navigation.go_to_page', page: examplePage },
    keywords: entry.keywords
      .filter(
        (keyword) =>
          ![
            ...(!availablePages.includes('workers')
              ? [
                  'workers',
                  'claude workers',
                  'terminal mode',
                  'worker terminals',
                ]
              : []),
          ].includes(keyword),
      )
      .concat(availablePages),
  };
}

/**
 * Searches the Advisor catalog. The main process passes shared-family rows
 * it composes (`sharedCatalog`) so they share one ranking and limit; this
 * module never copies them.
 */
export function searchAppAdvisorActions<
  TShared extends AgentActionCatalogEntry = never,
>(
  input: SearchAppAdvisorActionsInput = {},
  sharedCatalog: readonly TShared[] = [],
): AgentActionSearchResult<
  AgentActionSearchResultAction<
    AppAdvisorActionCatalogEntry | TShared,
    AppAdvisorActionSearchExtras
  >
> {
  // Older snapshot reducers can collapse arrays to count objects. Treat an
  // invalid transport shape as unknown availability, preserving unrelated
  // results without advertising gated destinations.
  const reportedPages = Array.isArray(input.availablePages)
    ? input.availablePages
    : undefined;
  const availablePages = Object.values(NAVIGATION_PAGE_MAP).filter(
    (page) =>
      !COMPATIBILITY_ALIAS_NAVIGATION_PAGES.has(page) &&
      (reportedPages
        ? reportedPages.includes(page)
        : !PAGES_REQUIRING_AVAILABILITY.has(page)),
  );
  const availableCatalog: (AppAdvisorActionCatalogEntry | TShared)[] = [
    ...APP_ADVISOR_ACTION_CATALOG.flatMap((entry) => {
      if (entry.hidden) return [];
      const projected = projectPageAvailability(entry, availablePages, input);
      return projected ? [projected] : [];
    }),
    ...sharedCatalog,
  ];
  const hookTriggersOf = (
    entry: AppAdvisorActionCatalogEntry | TShared,
  ): readonly HookWatcherTriggerCatalogEntry[] | undefined =>
    'hookTriggers' in entry ? entry.hookTriggers : undefined;
  return searchAgentActionCatalog(availableCatalog, input, {
    haystackTerms: (entry) =>
      (hookTriggersOf(entry) ?? []).flatMap((hookTrigger) => [
        hookTrigger.triggerName,
        hookTrigger.title,
        hookTrigger.hookKeyExamples.project,
        hookTrigger.hookKeyExamples.workspaceRoot,
        hookTrigger.hookKeyExamples.workspaceRepoPattern,
        ...hookTrigger.keywords,
      ]),
    resultExtras: (entry, query): Partial<AppAdvisorActionSearchExtras> => {
      const hookTriggers = hookTriggersOf(entry);
      return hookTriggers
        ? { hookTriggers: rankHookTriggers(hookTriggers, query) }
        : {};
    },
  });
}
